#include <iostream>

int main() {
    int orden{1};
    int repeticiones{3};
    int preparaciones{0};
    int revisiones{0};
    int desconocidas{0};
    for (int vuelta{0}; vuelta < repeticiones; ++vuelta) {
        switch (orden) {
        case 1:
            ++preparaciones;
            [[fallthrough]];
        case 2:
            ++revisiones;
            break;
        default:
            ++desconocidas;
            break;
        }
    }
    std::cout << "Préparations=" << preparaciones
              << ";Vérifications=" << revisiones
              << ";Inconnues=" << desconocidas;
    return 0;
}

